"""Pure self-contained consolidated renderer for approved result JSON.

API: build(summary: dict, views: dict) -> str. The caller owns IO and supplies
JSON-safe scalar slices (out-of-domain samples are None), never native arrays.
This renderer does not rank candidates, solve fields, validate physics, or load
an old GUI. B0 is always retained separately from the supplied provisional top5.
"""
import json


def build(summary, views):
    if not isinstance(summary, dict) or not isinstance(views, dict):
        raise TypeError("summary and views must be JSON metadata dictionaries")
    payload = json.dumps({"summary": summary, "views": views}, ensure_ascii=False,
                         allow_nan=False, separators=(",", ":"))
    payload = payload.replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e")
    payload = payload.replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    return _HTML.replace("__APPROVED_PAYLOAD__", payload)


